window.OPUS_PAGES["093"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Windwalker — A Kinetic Sculpture Simulation</title>\n<meta name=\"description\" content=\"Windwalker: a wind-driven walking sculpture on a beach, simulating the Jansen linkage with its canonical link lengths, solved joint by joint from circle intersections every frame.\">\n<meta name=\"theme-color\" content=\"#f0f4f5\">\n<style>\n:root{\n  --sky:#f0f4f5; --sea:#6fb3c7; --sand:#e9d8b4; --tube:#f4e3a1; --joint:#7d6a3a;\n  --paper:#fbfaf4; --ink:#2e3b44; --ink-soft:#5f6f78; --rule:rgba(61,143,168,.16); --coral:#d4553a; --blue:#3d8fa8;\n  --sans:\"Avenir Next\",\"Century Gothic\",\"URW Gothic\",\"Futura\",\"Segoe UI\",sans-serif;\n  --mono:\"SF Mono\",\"IBM Plex Mono\",\"Menlo\",\"Consolas\",\"DejaVu Sans Mono\",monospace;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;overflow-x:clip}\nbody{margin:0;background:var(--sky);color:var(--ink);font-family:var(--sans)}\n.skip{position:absolute;left:-999px;top:8px;z-index:30;background:var(--ink);color:#fff;padding:8px 14px;font-family:var(--mono)}\n.skip:focus{left:12px}\n.scene{position:relative;height:100vh;min-height:560px;overflow:hidden;touch-action:pan-y;cursor:grab;user-select:none;-webkit-user-select:none}\n.scene.dragging{cursor:grabbing}\n#beach{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}\n#beach:focus-visible{box-shadow:inset 0 0 0 3px var(--blue)}\n\n/* notebook label */\n.label{position:absolute;left:clamp(16px,3vw,40px);top:clamp(16px,3vh,32px);padding:16px 20px 15px 22px;max-width:420px;\n  background:\n    linear-gradient(90deg,transparent 14px,rgba(212,85,58,.35) 14px 15px,transparent 15px),\n    repeating-linear-gradient(0deg,transparent 0 21px,var(--rule) 21px 22px),\n    var(--paper);\n  box-shadow:0 1px 0 rgba(255,255,255,.8) inset,0 14px 30px -18px rgba(40,60,70,.5),0 0 0 1px rgba(46,59,68,.1);\n  transform:rotate(-.6deg)}\n.label::before{content:\"\";position:absolute;left:50%;top:-9px;width:70px;height:20px;margin-left:-35px;background:rgba(214,205,170,.62);transform:rotate(2deg);box-shadow:0 1px 2px rgba(0,0,0,.08)}\n.eyebrow{margin:0 0 4px 6px;font-family:var(--mono);font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--coral)}\nh1{margin:0 0 0 4px;font-weight:600;font-size:clamp(30px,3.6vw,46px);letter-spacing:.08em;line-height:1.02;text-transform:uppercase}\nh1 span{font-weight:300;color:var(--blue)}\n.tagline{margin:6px 0 0 6px;font-size:15px;line-height:1.45;color:var(--ink-soft)}\n\n/* live readouts */\n.hud{position:absolute;right:clamp(16px,3vw,40px);top:clamp(18px,3vh,34px);display:grid;grid-template-columns:repeat(3,auto);gap:0;font-family:var(--mono);background:rgba(251,250,244,.86);box-shadow:0 0 0 1px rgba(46,59,68,.12),0 10px 24px -16px rgba(40,60,70,.5)}\n.hud div{padding:9px 14px 8px;border-left:1px solid rgba(46,59,68,.1)}\n.hud div:first-child{border-left:0}\n.hud dt{font-size:9.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-soft)}\n.hud dd{margin:3px 0 0;font-size:17px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.hud dl{margin:0;display:contents}\n\n/* the single-leg diagram */\n.diagram{position:absolute;right:clamp(16px,3vw,40px);top:calc(clamp(18px,3vh,34px) + 78px);width:370px;padding:12px 14px 10px;\n  background:\n    repeating-linear-gradient(0deg,rgba(61,143,168,.13) 0 1px,transparent 1px 12px),\n    repeating-linear-gradient(90deg,rgba(61,143,168,.13) 0 1px,transparent 1px 12px),\n    var(--paper);\n  box-shadow:0 0 0 1px rgba(46,59,68,.14),0 16px 32px -18px rgba(40,60,70,.55);transition:opacity .35s,transform .35s}\n.diagram[hidden]{display:block;opacity:0;transform:translateY(-8px);pointer-events:none;visibility:hidden}\n.diagram h2{margin:0;font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-soft)}\n.diagram h2 b{color:var(--coral);font-weight:400}\n#leg{display:block;width:100%;height:270px}\n.diagram p{margin:2px 0 0;font-family:var(--mono);font-size:10.5px;line-height:1.5;color:var(--ink-soft)}\n\n/* control dock */\n.dock{position:absolute;left:50%;bottom:clamp(14px,3vh,28px);transform:translateX(-50%);display:flex;align-items:center;gap:6px;padding:8px;\n  background:rgba(251,250,244,.92);box-shadow:0 0 0 1px rgba(46,59,68,.14),0 18px 34px -20px rgba(40,60,70,.6);max-width:calc(100% - 24px)}\n.group{display:flex;align-items:center;gap:8px;padding:4px 10px;border-right:1px dashed rgba(46,59,68,.2)}\n.group:last-child{border-right:0}\n.glabel{font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-soft)}\n.wind{display:flex;flex-direction:column;gap:2px;min-width:210px}\n.wind .row{display:flex;justify-content:space-between;align-items:baseline}\n.wind output{font-family:var(--mono);font-size:13px;color:var(--ink)}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:24px;background:transparent;margin:0;cursor:pointer}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;background:linear-gradient(90deg,var(--blue),var(--coral));border-radius:2px}\ninput[type=range]::-moz-range-track{height:4px;background:linear-gradient(90deg,var(--blue),var(--coral));border-radius:2px}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;margin-top:-7px;border-radius:50%;background:var(--paper);border:2px solid var(--ink);box-shadow:0 2px 4px rgba(0,0,0,.2)}\ninput[type=range]::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:var(--paper);border:2px solid var(--ink)}\ninput[type=range]:focus-visible{outline:2px solid var(--blue);outline-offset:3px}\n.btn{font-family:var(--mono);font-size:12px;letter-spacing:.06em;color:var(--ink);background:var(--paper);border:1px solid rgba(46,59,68,.35);padding:8px 11px;cursor:pointer;transition:background .15s,color .15s,border-color .15s}\n.btn:hover{border-color:var(--ink)}\n.btn[aria-pressed=\"true\"]{background:var(--ink);color:var(--paper);border-color:var(--ink)}\n.btn:focus-visible{outline:2px solid var(--blue);outline-offset:2px}\n.btn.sq{width:34px;height:34px;padding:0;font-size:18px;line-height:1}\n.count{font-family:var(--mono);font-size:15px;min-width:64px;text-align:center}\n.count small{display:block;font-size:9.5px;letter-spacing:.12em;color:var(--ink-soft);text-transform:uppercase}\n.hint{position:absolute;left:50%;bottom:calc(clamp(14px,3vh,28px) + 64px);transform:translateX(-50%);font-family:var(--mono);font-size:11px;letter-spacing:.1em;color:rgba(46,59,68,.62);white-space:nowrap;pointer-events:none;transition:opacity .6s}\n\n/* notes below the beach */\n.notes{position:relative;padding:48px clamp(16px,5vw,64px) 56px;\n  background:\n    repeating-linear-gradient(0deg,transparent 0 27px,var(--rule) 27px 28px),\n    var(--paper);border-top:1px solid rgba(46,59,68,.12)}\n.notes-inner{max-width:1180px;margin:0 auto;display:grid;grid-template-columns:1.1fr 1fr;gap:48px;align-items:start}\n.notes h2{margin:0 0 12px;font-weight:600;font-size:22px;letter-spacing:.1em;text-transform:uppercase}\n.notes p{margin:0 0 14px;font-size:16px;line-height:1.7;color:#3c4a53;max-width:62ch}\n.notes code{font-family:var(--mono);font-size:14px;color:var(--coral)}\ntable{border-collapse:collapse;width:100%;font-family:var(--mono);font-size:13.5px}\ncaption{text-align:left;font-family:var(--mono);font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-soft);padding-bottom:8px}\nth,td{padding:7px 10px;border-bottom:1px solid rgba(46,59,68,.14);text-align:left}\nth{font-weight:400;color:var(--coral);width:40px}\ntd.v{text-align:right;font-variant-numeric:tabular-nums}\ntd.w{color:var(--ink-soft)}\n.credit{margin-top:22px;font-size:13px;color:var(--ink-soft)}\n.vh{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n\n@media (max-width:980px){\n  .diagram{width:320px}\n  #leg{height:230px}\n  .notes-inner{grid-template-columns:1fr;gap:28px}\n}\n@media (max-width:720px){\n  .scene{height:auto;min-height:0;display:flex;flex-direction:column;cursor:default}\n  .stage{position:relative;height:74vh;min-height:500px;cursor:grab}\n  .label{padding:12px 14px 11px 18px;max-width:calc(100% - 32px);transform:rotate(-.4deg)}\n  .eyebrow{font-size:9.5px}\n  .tagline{font-size:13px}\n  .hud{left:16px;right:auto;top:auto;bottom:14px;grid-template-columns:repeat(3,auto)}\n  .hud div{padding:7px 10px 6px}\n  .hud dd{font-size:14px}\n  .hint{bottom:78px;font-size:10px}\n  .dock{position:relative;left:auto;bottom:auto;transform:none;flex-wrap:wrap;justify-content:center;max-width:none;margin:0;gap:4px;box-shadow:0 -1px 0 rgba(46,59,68,.12)}\n  .group{border-right:0;padding:4px 6px}\n  .wind{min-width:0;width:100%}\n  .group.w{width:100%}\n  .diagram{position:relative;right:auto;top:auto;width:auto;margin:0}\n  .diagram[hidden]{display:none}\n  #leg{height:240px}\n}\n@media (min-width:721px){ .stage{position:absolute;inset:0} }\n@media (prefers-reduced-motion:reduce){ .diagram,.hint{transition:none} }\n</style>\n</head>\n<body>\n<a class=\"skip\" href=\"#dock\">Skip to the controls</a>\n<main class=\"scene\" id=\"scene\">\n  <div class=\"stage\" id=\"stage\">\n    <canvas id=\"beach\" tabindex=\"0\" role=\"img\" aria-label=\"A pale yellow wind-walking sculpture striding along a beach under a pale sky, leaving footprints in the sand. Drag or use the arrow keys to pan along the beach.\"></canvas>\n    <header class=\"label\">\n      <p class=\"eyebrow\">Kinetic sculpture simulation · field notes</p>\n      <h1>Wind<span>walker</span></h1>\n      <p class=\"tagline\">Every joint of every leg is solved from circle–circle intersections, sixty times a second, from the thirteen lengths of the Jansen linkage.</p>\n    </header>\n    <dl class=\"hud\" aria-label=\"Live readouts\">\n      <div><dt>crank angle</dt><dd id=\"hudTheta\">0°</dd></div>\n      <div><dt>pace</dt><dd id=\"hudPace\">0 m/min</dd></div>\n      <div><dt>walked</dt><dd id=\"hudDist\">0.0 m</dd></div>\n    </dl>\n    <p class=\"hint\" id=\"hint\">drag the beach to pan · the wind drives the crank</p>\n  </div>\n\n  <aside class=\"diagram\" id=\"diagram\" aria-label=\"Single leg diagram\" hidden>\n    <h2>fig. 1 <b>·</b> one leg, to scale · <span id=\"figTheta\">θ = 0°</span></h2>\n    <canvas id=\"leg\" role=\"img\" aria-label=\"A labelled diagram of one Jansen leg showing each link length and the foot's trajectory\"></canvas>\n    <p>Fixed pivots are hatched. The red curve is the path of the foot over one turn of the crank: a long, nearly flat stroke on the ground, then a quick lift back.</p>\n  </aside>\n\n  <div class=\"dock\" id=\"dock\" role=\"group\" aria-label=\"Controls\">\n    <div class=\"group w\">\n      <div class=\"wind\">\n        <div class=\"row\"><label class=\"glabel\" for=\"wind\">Wind</label><output id=\"windOut\" for=\"wind\">5.0 m/s</output></div>\n        <input type=\"range\" id=\"wind\" min=\"0\" max=\"12\" step=\"0.1\" value=\"5\">\n      </div>\n    </div>\n    <div class=\"group\">\n      <button type=\"button\" class=\"btn sq\" id=\"lessBtn\" aria-label=\"Remove a leg pair\">−</button>\n      <div class=\"count\" aria-live=\"polite\"><span id=\"pairs\">4</span> pairs<small id=\"legsN\">8 legs</small></div>\n      <button type=\"button\" class=\"btn sq\" id=\"moreBtn\" aria-label=\"Add a leg pair\">+</button>\n    </div>\n    <div class=\"group\">\n      <button type=\"button\" class=\"btn\" id=\"diagBtn\" aria-pressed=\"false\" aria-controls=\"diagram\">Leg diagram</button>\n      <button type=\"button\" class=\"btn\" id=\"traceBtn\" aria-pressed=\"true\">Trace paths</button>\n      <button type=\"button\" class=\"btn\" id=\"followBtn\" aria-pressed=\"true\">Follow</button>\n      <button type=\"button\" class=\"btn\" id=\"soundBtn\" aria-pressed=\"false\">Sound</button>\n    </div>\n  </div>\n</main>\n\n<section class=\"notes\" aria-labelledby=\"notesTitle\">\n  <div class=\"notes-inner\">\n    <div>\n      <h2 id=\"notesTitle\">How the legs are solved</h2>\n      <p>Each leg is a planar linkage hung from one fixed pivot on the body and driven by a crank of radius <code>m</code>. Given the crank angle θ, the crank tip sits at <code>(m·cos θ, m·sin θ)</code>. Every other joint is the meeting point of two links of known length, so it lies where two circles cross. The solver finds the upper joint from <code>j</code> and <code>b</code>, the knee from <code>k</code> and <code>c</code>, the outer corner of the upper triangle from <code>e</code> and <code>d</code>, the rear corner of the foot triangle from <code>f</code> and <code>g</code>, and finally the foot from <code>h</code> and <code>i</code>. Each time it keeps the one of the two crossings that matches the leg's assembly.</p>\n      <p>Pairs of legs are mirror images sharing a crank, and each pair runs at its own phase, so there is always a foot on the sand. The body is moved so that the foot in contact does not slip, and it settles to whatever height keeps that foot on the ground. The walk and the gentle bob come straight out of the geometry.</p>\n      <p class=\"credit\">Inspired by the Strandbeesten, the wind-walking beach creatures the Dutch artist Theo Jansen has been building since 1990. This is an original rendering and simulation, not a model of any particular beest.</p>\n    </div>\n    <table>\n      <caption>The linkage lengths used here (arbitrary units)</caption>\n      <tbody>\n        <tr><th>a</th><td class=\"w\">crank axle to fixed pivot, horizontal</td><td class=\"v\">38.0</td></tr>\n        <tr><th>l</th><td class=\"w\">crank axle to fixed pivot, vertical</td><td class=\"v\">7.8</td></tr>\n        <tr><th>m</th><td class=\"w\">crank radius</td><td class=\"v\">15.0</td></tr>\n        <tr><th>j</th><td class=\"w\">crank to upper joint</td><td class=\"v\">50.0</td></tr>\n        <tr><th>k</th><td class=\"w\">crank to knee</td><td class=\"v\">61.9</td></tr>\n        <tr><th>b</th><td class=\"w\">pivot to upper joint</td><td class=\"v\">41.5</td></tr>\n        <tr><th>c</th><td class=\"w\">pivot to knee</td><td class=\"v\">39.3</td></tr>\n        <tr><th>d</th><td class=\"w\">pivot to outer corner (upper triangle)</td><td class=\"v\">40.1</td></tr>\n        <tr><th>e</th><td class=\"w\">upper joint to outer corner (upper triangle)</td><td class=\"v\">55.8</td></tr>\n        <tr><th>f</th><td class=\"w\">outer corner to rear corner</td><td class=\"v\">39.4</td></tr>\n        <tr><th>g</th><td class=\"w\">knee to rear corner (foot triangle)</td><td class=\"v\">36.7</td></tr>\n        <tr><th>h</th><td class=\"w\">rear corner to foot (foot triangle)</td><td class=\"v\">65.7</td></tr>\n        <tr><th>i</th><td class=\"w\">knee to foot (foot triangle)</td><td class=\"v\">49.0</td></tr>\n      </tbody>\n    </table>\n  </div>\n</section>\n\n<script>\n(() => {\n  'use strict';\n  const $ = (s) => document.querySelector(s);\n  const mq = window.matchMedia('(prefers-reduced-motion: reduce)');\n  let reduce = mq.matches;\n\n  /* ================= the linkage ================= */\n  const L = { a: 38, b: 41.5, c: 39.3, d: 40.1, e: 55.8, f: 39.4, g: 36.7, h: 65.7, i: 49, j: 50, k: 61.9, l: 7.8, m: 15 };\n  // intersection of circle(p0, r0) and circle(p1, r1); s picks the branch. Writes into o[oi], o[oi+1].\n  function cross(o, oi, x0, y0, r0, x1, y1, r1, s) {\n    const dx = x1 - x0, dy = y1 - y0, D = Math.hypot(dx, dy) || 1e-6;\n    const A = (r0 * r0 - r1 * r1 + D * D) / (2 * D);\n    const H = Math.sqrt(Math.max(0, r0 * r0 - A * A));\n    const xm = x0 + A * dx / D, ym = y0 + A * dy / D;\n    o[oi] = xm - s * H * dy / D; o[oi + 1] = ym + s * H * dx / D;\n  }\n  // joints in y-up leg space, crank axle at the origin: O Z X Y W V U T (8 points, 16 numbers)\n  function solve(theta, o) {\n    const Zx = -L.a, Zy = -L.l;\n    o[0] = 0; o[1] = 0; o[2] = Zx; o[3] = Zy;\n    o[4] = L.m * Math.cos(theta); o[5] = L.m * Math.sin(theta);\n    cross(o, 6, o[4], o[5], L.j, Zx, Zy, L.b, -1);          // Y  upper joint\n    cross(o, 8, o[4], o[5], L.k, Zx, Zy, L.c, 1);           // W  knee\n    cross(o, 10, o[6], o[7], L.e, Zx, Zy, L.d, -1);         // V  outer corner of the upper triangle\n    cross(o, 12, o[10], o[11], L.f, o[8], o[9], L.g, -1);   // U  rear corner of the foot triangle\n    cross(o, 14, o[12], o[13], L.h, o[8], o[9], L.i, -1);   // T  foot\n    return o;\n  }\n  // links as index pairs into the joint list (O0 Z1 X2 Y3 W4 V5 U6 T7)\n  const LINKS = [[0, 2, 'm'], [2, 3, 'j'], [2, 4, 'k'], [1, 3, 'b'], [1, 4, 'c'], [3, 5, 'e'], [1, 5, 'd'], [5, 6, 'f'], [4, 6, 'g'], [6, 7, 'h'], [4, 7, 'i']];\n  // one full turn of the foot, for trace curves and the diagram\n  const CURVE = [];\n  (() => { const o = new Float64Array(16); for (let k = 0; k <= 180; k++) { solve(k / 180 * Math.PI * 2, o); CURVE.push([o[14], o[15]]); } })();\n  const FOOT_MIN = Math.min(...CURVE.map((p) => p[1]));\n\n  /* ================= creature ================= */\n  const SPACING = 104;\n  let pairs = window.innerWidth < 720 ? 3 : 4;\n  let legs = [];            // { pair, mirror, phase, depth, buf, foot:[x,y], prevFoot, ground }\n  function buildLegs() {\n    const keep = legs;\n    legs = [];\n    for (let p = 0; p < pairs; p++) {\n      const off = (p - (pairs - 1) / 2) * SPACING;\n      const phase = (p * 2 * Math.PI * 0.618) % (Math.PI * 2);\n      const depth = p % 2;   // alternate stations sit on the near and far side of the spine\n      for (const mirror of [false, true]) legs.push({ p, off, mirror, phase, depth, buf: new Float64Array(16), fx: 0, fy: 0, pfx: NaN, pfy: 0, down: false });\n    }\n    if (keep.length) legs.forEach((lg) => { lg.pfx = NaN; });\n    $('#pairs').textContent = pairs; $('#legsN').textContent = pairs * 2 + ' legs';\n    $('#lessBtn').disabled = pairs <= 1; $('#moreBtn').disabled = pairs >= 8;\n  }\n  function legJoints(lg, theta) {\n    const o = lg.buf;\n    if (!lg.mirror) solve(theta + lg.phase, o);\n    else { solve(Math.PI - (theta + lg.phase), o); for (let q = 0; q < 16; q += 2) o[q] = -o[q]; }\n    return o;\n  }\n\n  /* ================= world state ================= */\n  let theta = 0, bodyX = 0, bodyY = -FOOT_MIN, camX = 0, follow = true, walked = 0, pace = 0;\n  let wind = 5, windShown = 5, trace = true;\n  const prints = []; const PRINTS = 420;\n  for (let q = 0; q < PRINTS; q++) prints.push({ on: false, x: 0, depth: 0, age: 0, mirror: false });\n  let printIdx = 0;\n  const puffs = []; for (let q = 0; q < 80; q++) puffs.push({ on: false, x: 0, y: 0, vx: 0, vy: 0, life: 0 });\n  const grains = []; for (let q = 0; q < 90; q++) grains.push({ x: Math.random(), y: Math.random(), l: Math.random() });\n\n  function step(dt) {\n    windShown += (wind - windShown) * Math.min(1, dt * 2);\n    const omega = windShown * 0.32 * (reduce ? 0.6 : 1);\n    theta -= omega * dt;                                   // turning this way walks the beest to the right\n    let lowest = Infinity, contact = null;\n    for (const lg of legs) {\n      const o = legJoints(lg, theta);\n      lg.fx = o[14] + lg.off; lg.fy = o[15];\n      if (lg.fy < lowest) { lowest = lg.fy; contact = lg; }\n    }\n    // keep the contact foot planted: the body moves by the opposite of its motion in body space\n    if (contact && !isNaN(contact.pfx)) {\n      const dx = -(contact.fx - contact.pfx);\n      bodyX += dx; walked += Math.abs(dx);\n      pace += ((Math.abs(dx) / Math.max(dt, 1e-3)) - pace) * Math.min(1, dt * 3);\n    }\n    bodyY += ((-lowest) - bodyY) * Math.min(1, dt * 30);\n    for (const lg of legs) {\n      const onGround = lg.fy < lowest + 0.9;\n      if (onGround && !lg.down && !isNaN(lg.pfx)) touchDown(lg);\n      lg.down = onGround;\n      lg.pfx = lg.fx; lg.pfy = lg.fy;\n    }\n    // with the diagram open on a wide screen, frame the beest a little left of centre\n    const lead = diagOn && W > 720 ? Math.min(W * 0.1, 170) / S : 0;\n    // aim at the beest's visual middle (far legs sit a little to the right) plus a touch of look-ahead\n    if (follow) camX += (bodyX + 8 + lead + pace * 0.35 - camX) * Math.min(1, dt * 2.2);\n  }\n  function touchDown(lg) {\n    const pr = prints[printIdx]; printIdx = (printIdx + 1) % PRINTS;\n    pr.on = true; pr.x = bodyX + lg.fx; pr.depth = lg.depth; pr.age = 0; pr.mirror = lg.mirror;\n    if (!reduce) for (let q = 0; q < 4; q++) { const pf = puffs.find((z) => !z.on); if (!pf) break; pf.on = true; pf.x = bodyX + lg.fx; pf.y = 0; pf.vx = (Math.random() - 0.3) * 8 + windShown * 1.2; pf.vy = 6 + Math.random() * 8; pf.life = 1; pf.depth = lg.depth; }\n    if (soundOn) tock(lg.depth);\n  }\n\n  /* ================= canvas ================= */\n  const cv = $('#beach'), ctx = cv.getContext('2d');\n  const stage = $('#stage');\n  let W = 0, H = 0, dpr = 1, S = 2, groundY = 0, horizonY = 0, shoreY = 0;\n  function resize() {\n    dpr = Math.min(2, window.devicePixelRatio || 1);\n    const r = stage.getBoundingClientRect(); W = r.width; H = r.height;\n    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);\n    const phone = window.innerWidth < 720;\n    S = phone ? Math.min(H * 0.5 / 250, W * 0.86 / ((pairs - 1) * SPACING + 250)) : Math.min(H * 0.56 / 230, W * 0.86 / 560);\n    groundY = H * (phone ? 0.8 : 0.79); horizonY = H * (phone ? 0.5 : 0.47); shoreY = H * (phone ? 0.6 : 0.585);\n    buildSky();\n    sizeLeg();\n  }\n  // world x (linkage units) to screen x\n  const sx = (wx) => W / 2 + (wx - camX) * S;\n  const depthDY = (dp) => dp ? -S * 16 : 0;          // far-side legs stand a little higher on the canvas\n  const depthDX = (dp) => dp ? S * 10 : 0;\n\n  // pre-rendered sky with a soft sun, rebuilt on resize\n  let skyCv = null;\n  function buildSky() {\n    skyCv = document.createElement('canvas'); skyCv.width = cv.width; skyCv.height = Math.ceil(shoreY * dpr) + 2;\n    const x = skyCv.getContext('2d'); x.scale(dpr, dpr);\n    const g = x.createLinearGradient(0, 0, 0, horizonY);\n    g.addColorStop(0, '#d9e6eb'); g.addColorStop(0.55, '#e9f0f2'); g.addColorStop(1, '#f6f3ea');\n    x.fillStyle = g; x.fillRect(0, 0, W, horizonY + 1);\n    const sunX = W * 0.72, sunY = horizonY * 0.42;\n    const sg = x.createRadialGradient(sunX, sunY, 0, sunX, sunY, H * 0.34);\n    sg.addColorStop(0, 'rgba(255,252,236,.95)'); sg.addColorStop(0.08, 'rgba(255,250,228,.8)'); sg.addColorStop(0.3, 'rgba(255,246,220,.25)'); sg.addColorStop(1, 'rgba(255,246,220,0)');\n    x.fillStyle = sg; x.fillRect(0, 0, W, horizonY);\n    // the sea\n    const sgr = x.createLinearGradient(0, horizonY, 0, shoreY);\n    sgr.addColorStop(0, '#5d9fb6'); sgr.addColorStop(0.5, '#6fb3c7'); sgr.addColorStop(1, '#93cad6');\n    x.fillStyle = sgr; x.fillRect(0, horizonY, W, shoreY - horizonY + 2);\n    x.fillStyle = 'rgba(255,255,255,.35)'; x.fillRect(0, horizonY, W, 1);\n    // glitter under the sun\n    const gl = x.createLinearGradient(sunX - W * 0.12, 0, sunX + W * 0.12, 0);\n    gl.addColorStop(0, 'rgba(255,255,255,0)'); gl.addColorStop(0.5, 'rgba(255,255,245,.35)'); gl.addColorStop(1, 'rgba(255,255,255,0)');\n    x.fillStyle = gl; x.fillRect(sunX - W * 0.12, horizonY, W * 0.24, (shoreY - horizonY) * 0.7);\n  }\n\n  // clouds: soft blobs at three depths\n  const clouds = [];\n  (() => { let s = 7; const r = () => ((s = (s * 16807) % 2147483647) / 2147483647); for (let q = 0; q < 14; q++) clouds.push({ x: r() * 3000, y: r(), z: q % 3, w: 90 + r() * 170, puffs: 4 + (r() * 4 | 0), seed: r() * 100 }); })();\n  let cloudDrift = 0;\n  function drawClouds(x) {\n    for (const c of clouds) {\n      const par = [0.08, 0.16, 0.28][c.z], sc = [0.6, 0.8, 1.05][c.z];\n      const span = W + 700;\n      let px = ((c.x - camX * S * par + cloudDrift * (0.4 + c.z * 0.3)) % span + span) % span - 350;\n      const py = horizonY * (0.12 + c.y * 0.55) * (1 - c.z * 0.1);\n      const w = c.w * sc * Math.max(0.6, W / 1400);\n      x.globalAlpha = [0.55, 0.7, 0.85][c.z];\n      for (let q = 0; q < c.puffs; q++) {\n        const ox = (q / (c.puffs - 1) - 0.5) * w, oy = -Math.sin(q / (c.puffs - 1) * Math.PI) * w * 0.18 + Math.sin(c.seed + q) * w * 0.04;\n        const rr = w * (0.2 + 0.1 * Math.sin(c.seed * 3 + q * 1.7));\n        const g = x.createRadialGradient(px + ox, py + oy - rr * 0.2, 0, px + ox, py + oy, rr);\n        g.addColorStop(0, 'rgba(255,255,255,1)'); g.addColorStop(0.55, 'rgba(255,255,255,.85)'); g.addColorStop(0.8, 'rgba(250,252,253,.35)'); g.addColorStop(1, 'rgba(255,255,255,0)');\n        x.fillStyle = g; x.beginPath(); x.arc(px + ox, py + oy, rr, 0, Math.PI * 2); x.fill();\n      }\n      const bg = x.createLinearGradient(0, py, 0, py + w * 0.14);\n      bg.addColorStop(0, 'rgba(214,224,230,0)'); bg.addColorStop(1, 'rgba(206,218,226,.4)');\n      x.fillStyle = bg; x.beginPath(); x.ellipse(px, py + w * 0.06, w * 0.55, w * 0.08, 0, 0, Math.PI * 2); x.fill();\n    }\n    x.globalAlpha = 1;\n  }\n\n  function hash(n) { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); }\n  function drawSea(x, t) {\n    // wave lines riding in toward the shore\n    x.strokeStyle = 'rgba(255,255,255,.45)'; x.lineWidth = 1;\n    for (let q = 0; q < 7; q++) {\n      const y = horizonY + (shoreY - horizonY) * ((q + (t * 0.05) % 1) / 7);\n      const k = (y - horizonY) / (shoreY - horizonY);\n      x.globalAlpha = 0.15 + k * 0.45;\n      x.beginPath();\n      const off = -camX * S * (0.3 + k * 0.4);\n      for (let px = -20; px <= W + 20; px += 16) {\n        const yy = y + Math.sin((px - off) * 0.018 + q * 2 + t * 0.8) * (1 + k * 2.5);\n        if (px === -20) x.moveTo(px, yy); else x.lineTo(px, yy);\n      }\n      x.stroke();\n    }\n    x.globalAlpha = 1;\n    // the swash: foam sliding up and back\n    const sw = Math.sin(t * 0.6) * 0.5 + 0.5;\n    const edge = shoreY + 6 + sw * (H * 0.02);\n    const off = -camX * S * 0.7;\n    x.fillStyle = 'rgba(170,205,210,.55)';\n    x.beginPath(); x.moveTo(0, shoreY - 2);\n    for (let px = 0; px <= W + 16; px += 16) x.lineTo(px, edge + Math.sin((px - off) * 0.012 + t * 0.5) * 5 + Math.sin((px - off) * 0.031) * 3);\n    x.lineTo(W, shoreY - 2); x.closePath(); x.fill();\n    x.strokeStyle = 'rgba(255,255,255,.95)'; x.lineWidth = 2;\n    x.beginPath();\n    for (let px = 0; px <= W + 16; px += 16) { const yy = edge + Math.sin((px - off) * 0.012 + t * 0.5) * 5 + Math.sin((px - off) * 0.031) * 3; if (px === 0) x.moveTo(px, yy); else x.lineTo(px, yy); }\n    x.stroke();\n  }\n  // ground parallax: exactly 1 on the line the beest walks, less toward the sea, more toward the viewer\n  const sandPar = (y) => 1 + (y - groundY) / (H - shoreY) * 0.8;\n  function drawSand(x, t) {\n    const g = x.createLinearGradient(0, shoreY, 0, H);\n    g.addColorStop(0, '#d7c29a'); g.addColorStop(0.12, '#e2cfa8'); g.addColorStop(0.35, '#e9d8b4'); g.addColorStop(1, '#efe2c4');\n    x.fillStyle = g; x.fillRect(0, shoreY, W, H - shoreY);\n    // wind ripples, drawn in world space so they scroll with the ground\n    x.strokeStyle = 'rgba(160,130,85,.16)'; x.lineWidth = 1.2;\n    for (let q = 0; q < 16; q++) {\n      const k = q / 15, y = shoreY + (H - shoreY) * (0.08 + k * 0.9);\n      const par = sandPar(y);\n      x.beginPath();\n      for (let px = -10; px <= W + 10; px += 10) {\n        const wx = px / S / par + camX * 1;\n        const yy = y + Math.sin(wx * 0.09 + q * 1.3) * (2 + k * 3) + Math.sin(wx * 0.23 + q) * 1.2;\n        if (px === -10) x.moveTo(px, yy); else x.lineTo(px, yy);\n      }\n      x.stroke();\n    }\n    // shells and pebbles, placed per world tile\n    const tile = 60, x0 = Math.floor((camX - W / 2 / S) / tile) - 1, x1 = Math.floor((camX + W / 2 / S) / tile) + 1;\n    for (let tI = x0; tI <= x1; tI++) {\n      for (let q = 0; q < 2; q++) {\n        const hsh = hash(tI * 7 + q * 13);\n        const wx = (tI + hash(tI * 3.1 + q)) * tile, k = hash(tI * 1.7 + q * 5.3);\n        const y = shoreY + (H - shoreY) * (0.1 + k * 0.85);\n        const px = W / 2 + (wx - camX) * S * sandPar(y);\n        if (px < -10 || px > W + 10) continue;\n        const r = (1 + hsh * 2.4) * (0.6 + k) * Math.max(0.6, S / 2);\n        if (hsh < 0.5) { x.fillStyle = hsh < 0.25 ? 'rgba(150,125,95,.55)' : 'rgba(255,250,240,.8)'; x.beginPath(); x.ellipse(px, y, r, r * 0.6, hsh * 3, 0, Math.PI * 2); x.fill(); }\n        else if (hsh < 0.62) { x.strokeStyle = 'rgba(214,150,130,.75)'; x.lineWidth = 1; x.beginPath(); x.arc(px, y, r * 1.3, Math.PI * 1.05, Math.PI * 1.95); x.stroke(); x.beginPath(); x.moveTo(px, y); x.lineTo(px - r, y - r * 0.7); x.moveTo(px, y); x.lineTo(px + r, y - r * 0.7); x.moveTo(px, y); x.lineTo(px, y - r * 1.2); x.stroke(); }\n      }\n    }\n  }\n  function drawPrints(x, dt) {\n    for (const p of prints) {\n      if (!p.on) continue;\n      p.age += dt;\n      const a = Math.max(0, 1 - p.age / 45);\n      if (a <= 0) { p.on = false; continue; }\n      const px = sx(p.x) + depthDX(p.depth), py = groundY + depthDY(p.depth) + 3;\n      if (px < -30 || px > W + 30) continue;\n      const w = S * 6.5 * (p.depth ? 0.85 : 1), h = S * 1.9 * (p.depth ? 0.85 : 1);\n      x.fillStyle = `rgba(255,248,230,${(0.5 * a).toFixed(3)})`; x.beginPath(); x.ellipse(px + w * 0.1, py + h * 0.6, w * 1.1, h * 0.55, 0, 0, Math.PI * 2); x.fill();\n      x.fillStyle = `rgba(138,104,62,${(0.42 * a).toFixed(3)})`; x.beginPath(); x.ellipse(px, py, w, h, 0, 0, Math.PI * 2); x.fill();\n      x.fillStyle = `rgba(110,82,48,${(0.25 * a).toFixed(3)})`; x.beginPath(); x.ellipse(px - w * 0.2, py - h * 0.25, w * 0.6, h * 0.45, 0, 0, Math.PI * 2); x.fill();\n    }\n  }\n\n  /* --- tubes --- */\n  function tube(x, ax, ay, bx, by, w, far) {\n    x.lineWidth = w + 2.2; x.strokeStyle = far ? '#b8a67a' : '#b39a52';\n    x.beginPath(); x.moveTo(ax, ay); x.lineTo(bx, by); x.stroke();\n    x.lineWidth = w; x.strokeStyle = far ? '#e9dfbd' : '#f4e3a1';\n    x.beginPath(); x.moveTo(ax, ay); x.lineTo(bx, by); x.stroke();\n    if (w > 2.2) {\n      x.lineWidth = Math.max(0.8, w * 0.28); x.strokeStyle = far ? 'rgba(255,255,248,.55)' : 'rgba(255,252,232,.95)';\n      x.beginPath(); x.moveTo(ax - w * 0.18, ay - w * 0.18); x.lineTo(bx - w * 0.18, by - w * 0.18); x.stroke();\n    }\n  }\n  function joint(x, px, py, r, far) {\n    x.fillStyle = far ? '#a39470' : '#7d6a3a'; x.beginPath(); x.arc(px, py, r, 0, Math.PI * 2); x.fill();\n    x.fillStyle = far ? '#d9cfae' : '#c8b377'; x.beginPath(); x.arc(px - r * 0.2, py - r * 0.2, r * 0.42, 0, Math.PI * 2); x.fill();\n  }\n  const P = (lg, o, q) => [sx(bodyX + lg.off + o[q]) + depthDX(lg.depth), groundY - (bodyY + o[q + 1]) * S + depthDY(lg.depth)];\n\n  function drawLeg(x, lg) {\n    const o = lg.buf, far = lg.depth === 1;\n    const w = Math.max(1.6, S * (far ? 2.6 : 3.2)), jr = Math.max(1.5, S * (far ? 1.9 : 2.3));\n    const pts = [];\n    for (let q = 0; q < 16; q += 2) pts.push(P(lg, o, q));\n    // lightly glazed triangles read as rigid bodies\n    x.fillStyle = far ? 'rgba(244,227,161,.10)' : 'rgba(244,227,161,.2)';\n    x.beginPath(); x.moveTo(pts[1][0], pts[1][1]); x.lineTo(pts[3][0], pts[3][1]); x.lineTo(pts[5][0], pts[5][1]); x.closePath(); x.fill();\n    x.beginPath(); x.moveTo(pts[4][0], pts[4][1]); x.lineTo(pts[6][0], pts[6][1]); x.lineTo(pts[7][0], pts[7][1]); x.closePath(); x.fill();\n    x.lineCap = 'round';\n    for (const [aI, bI, nm] of LINKS) tube(x, pts[aI][0], pts[aI][1], pts[bI][0], pts[bI][1], nm === 'm' ? w * 1.25 : w, far);\n    for (let q = 1; q < 7; q++) joint(x, pts[q][0], pts[q][1], jr, far);\n    // the foot: a small sole\n    const [fx, fy] = pts[7];\n    x.fillStyle = far ? '#a39470' : '#6f5d32';\n    x.beginPath(); x.ellipse(fx, fy + S * 0.4, S * 3.4, S * 1.2, 0, 0, Math.PI * 2); x.fill();\n  }\n\n  function drawBody(x, t) {\n    const off0 = -(pairs - 1) / 2 * SPACING, off1 = (pairs - 1) / 2 * SPACING;\n    const Y = (y) => groundY - (bodyY + y) * S;\n    const X = (wx) => sx(bodyX + wx);\n    const w = Math.max(2, S * 3.6);\n    x.lineCap = 'round';\n    // spine and lower beam\n    tube(x, X(off0 - 52), Y(22), X(off1 + 52), Y(22), w * 1.1, false);\n    tube(x, X(off0 - 40), Y(-7.8), X(off1 + 40), Y(-7.8), w * 0.8, false);\n    for (let p = 0; p < pairs; p++) {\n      const o = off0 + p * SPACING;\n      tube(x, X(o - 38), Y(-7.8), X(o), Y(22), w * 0.7, false);\n      tube(x, X(o + 38), Y(-7.8), X(o), Y(22), w * 0.7, false);\n      tube(x, X(o), Y(0), X(o), Y(22), w * 0.8, false);\n    }\n    // mast and sails: each sail billows with the wind, its trailing edge ruffling\n    const mastTop = 118, n = Math.max(2, Math.min(4, pairs));\n    const sailW = (off1 - off0 + 104) / n;\n    for (let q = 0; q < n; q++) {\n      const lx = off0 - 52 + q * sailW + sailW * 0.12, rx = lx + sailW * 0.7;\n      const baseY = 30, topY = mastTop - 10 - (q % 2) * 14;\n      const billow = (3 + windShown * 1.8) * (reduce ? 0.5 : 1);\n      const flap = reduce ? 0 : Math.sin(t * (2.2 + windShown * 0.35) + q * 1.9) * (1.2 + windShown * 0.4);\n      const g = x.createLinearGradient(X(lx), Y(topY), X(rx), Y(baseY));\n      g.addColorStop(0, 'rgba(255,255,252,.82)'); g.addColorStop(0.55, 'rgba(244,246,240,.62)'); g.addColorStop(1, 'rgba(226,232,228,.5)');\n      x.fillStyle = g;\n      x.beginPath();\n      x.moveTo(X(lx), Y(baseY));\n      x.lineTo(X(lx + 6), Y(topY));\n      x.quadraticCurveTo(X((lx + rx) / 2 + billow * 0.6), Y(topY + billow * 0.25 + flap * 0.3), X(rx + billow * 0.8 + flap), Y(topY - 18));\n      x.quadraticCurveTo(X(rx + billow * 1.3 + flap * 0.6), Y((topY + baseY) / 2), X(rx), Y(baseY));\n      x.closePath(); x.fill();\n      x.strokeStyle = 'rgba(179,154,82,.7)'; x.lineWidth = Math.max(1, S * 0.7); x.stroke();\n      // battens\n      x.strokeStyle = 'rgba(179,154,82,.35)'; x.lineWidth = Math.max(0.8, S * 0.45);\n      for (let bI = 1; bI < 4; bI++) { const f = bI / 4; x.beginPath(); x.moveTo(X(lx + 3 * f + 3), Y(baseY + (topY - baseY) * f)); x.quadraticCurveTo(X((lx + rx) / 2 + billow * f), Y(baseY + (topY - baseY) * f + 2), X(rx + billow * 1.1 * (1 - Math.abs(f - 0.5)) + flap * f), Y(baseY + (topY - baseY) * f - 6 * f)); x.stroke(); }\n      tube(x, X(lx), Y(baseY - 4), X(lx + 6), Y(topY + 4), w * 0.7, false);\n    }\n    // pennant on the first mast, streaming downwind\n    const mx = off0 - 52 + sailW * 0.08 + 6, my = mastTop - 8;\n    tube(x, X(mx), Y(my - 10), X(mx), Y(my + 18), w * 0.6, false);\n    const pl = 16 + windShown * 1.6;\n    x.fillStyle = '#d4553a';\n    x.beginPath(); x.moveTo(X(mx), Y(my + 18));\n    x.quadraticCurveTo(X(mx + pl * 0.5), Y(my + 16 + (reduce ? 0 : Math.sin(t * 7) * 2)), X(mx + pl), Y(my + 14 + (reduce ? 0 : Math.sin(t * 7 + 1.5) * 2.5)));\n    x.lineTo(X(mx), Y(my + 10)); x.closePath(); x.fill();\n    // crank hubs\n    for (let p = 0; p < pairs; p++) joint(x, X(off0 + p * SPACING), Y(0), Math.max(2.2, S * 3.4), false);\n  }\n\n  function drawTraces(x) {\n    x.setLineDash([Math.max(2, S * 2), Math.max(2, S * 2)]);\n    x.lineWidth = Math.max(1, S * 0.7);\n    for (const lg of legs) {\n      const far = lg.depth === 1;\n      x.strokeStyle = far ? 'rgba(212,85,58,.35)' : 'rgba(212,85,58,.75)';\n      x.beginPath();\n      CURVE.forEach(([cx, cy], q) => {\n        const wx = lg.mirror ? -cx : cx;\n        const px = sx(bodyX + lg.off + wx) + depthDX(lg.depth), py = groundY - (bodyY + cy) * S + depthDY(lg.depth);\n        if (q) x.lineTo(px, py); else x.moveTo(px, py);\n      });\n      x.stroke();\n    }\n    x.setLineDash([]);\n    for (const lg of legs) {\n      const [fx, fy] = P(lg, lg.buf, 14);\n      x.fillStyle = lg.depth ? 'rgba(212,85,58,.5)' : '#d4553a';\n      x.beginPath(); x.arc(fx, fy, Math.max(2, S * 1.6), 0, Math.PI * 2); x.fill();\n    }\n  }\n\n  // birds far off\n  const birds = [{ x: 0.2, y: 0.25, s: 1, ph: 0 }, { x: 0.26, y: 0.22, s: 0.8, ph: 1.3 }, { x: 0.62, y: 0.18, s: 0.7, ph: 2.1 }];\n  function drawBirds(x, t) {\n    x.strokeStyle = 'rgba(70,88,98,.55)'; x.lineWidth = 1.3; x.lineCap = 'round';\n    for (const b of birds) {\n      const px = ((b.x * W + t * (10 + windShown * 3) * b.s - camX * S * 0.05) % (W + 80) + W + 80) % (W + 80) - 40;\n      const py = horizonY * b.y + Math.sin(t * 0.7 + b.ph) * 6;\n      const fl = reduce ? 0.4 : Math.sin(t * 6 + b.ph) * 0.6;\n      const s = 7 * b.s;\n      x.beginPath(); x.moveTo(px - s, py - s * (0.3 + fl * 0.5)); x.quadraticCurveTo(px - s * 0.4, py - s * 0.5, px, py); x.quadraticCurveTo(px + s * 0.4, py - s * 0.5, px + s, py - s * (0.3 + fl * 0.5)); x.stroke();\n    }\n  }\n\n  let lastT = 0, time = 0, hudT = 0;\n  function frame(now) {\n    requestAnimationFrame(frame);\n    if (document.hidden) { lastT = now; return; }\n    const dt = Math.min(0.05, lastT ? (now - lastT) / 1000 : 0.016); lastT = now;\n    time += dt;\n    step(dt);\n    cloudDrift += dt * (4 + windShown * 5);\n    render(dt);\n    if (diagOn) drawDiagram();\n    if (now - hudT > 120) { hudT = now; hud(); }\n    if (soundOn) windSound();\n  }\n  function render(dt) {\n    const x = ctx;\n    x.setTransform(dpr, 0, 0, dpr, 0, 0);\n    x.drawImage(skyCv, 0, 0, W, skyCv.height / dpr);\n    drawClouds(x);\n    drawBirds(x, time);\n    drawSea(x, time);\n    drawSand(x, time);\n    drawPrints(x, dt);\n    // soft shadow beneath the beest\n    const off0 = -(pairs - 1) / 2 * SPACING - 110, off1 = (pairs - 1) / 2 * SPACING + 110;\n    const shx = sx(bodyX + (off0 + off1) / 2) + S * 10, shw = (off1 - off0) * S * 0.55;\n    const sg = x.createRadialGradient(shx, groundY + 4, 0, shx, groundY + 4, shw);\n    sg.addColorStop(0, 'rgba(120,95,60,.22)'); sg.addColorStop(1, 'rgba(120,95,60,0)');\n    x.fillStyle = sg; x.save(); x.translate(shx, groundY + 4); x.scale(1, 0.12); x.translate(-shx, -(groundY + 4)); x.beginPath(); x.arc(shx, groundY + 4, shw, 0, Math.PI * 2); x.fill(); x.restore();\n    // far legs, body and sails, near legs\n    for (const lg of legs) if (lg.depth === 1) drawLeg(x, lg);\n    drawBody(x, time);\n    for (const lg of legs) if (lg.depth === 0) drawLeg(x, lg);\n    if (trace) drawTraces(x);\n    // sand puffs and blowing grains\n    for (const p of puffs) {\n      if (!p.on) continue;\n      p.life -= dt * 1.4; if (p.life <= 0) { p.on = false; continue; }\n      p.x += p.vx * dt; p.y += p.vy * dt; p.vy -= 20 * dt;\n      const px = sx(p.x) + depthDX(p.depth), py = groundY + depthDY(p.depth) - Math.max(0, p.y) * S;\n      x.fillStyle = `rgba(214,194,150,${(p.life * 0.6).toFixed(3)})`; x.beginPath(); x.arc(px, py, S * 1.2 * (1.5 - p.life), 0, Math.PI * 2); x.fill();\n    }\n    if (!reduce && windShown > 2) {\n      x.strokeStyle = 'rgba(200,178,132,.45)'; x.lineWidth = 1;\n      for (const gI of grains) {\n        gI.x += dt * (0.05 + windShown * 0.03) * (0.5 + gI.l);\n        if (gI.x > 1.05) { gI.x = -0.05; gI.y = Math.random(); }\n        const px = gI.x * W, py = shoreY + (H - shoreY) * (0.2 + gI.y * 0.8) - Math.sin(gI.x * 20 + gI.l * 9) * 3;\n        x.globalAlpha = Math.min(1, (windShown - 2) / 5) * (0.3 + gI.l * 0.5);\n        x.beginPath(); x.moveTo(px, py); x.lineTo(px - 4 - windShown * 0.8 * gI.l, py + 0.5); x.stroke();\n      }\n      x.globalAlpha = 1;\n    }\n  }\n\n  /* ================= readouts ================= */\n  function hud() {\n    const deg = (((theta * 180 / Math.PI) % 360) + 360) % 360;\n    $('#hudTheta').textContent = deg.toFixed(0) + '°';\n    // one unit is taken as one centimetre: the leg stands a little over a metre tall\n    $('#hudPace').textContent = (pace * 0.6).toFixed(1) + ' m/min';\n    $('#hudDist').textContent = (walked / 100).toFixed(1) + ' m';\n    $('#figTheta').textContent = 'θ = ' + deg.toFixed(0) + '°';\n  }\n\n  /* ================= the single-leg diagram ================= */\n  const legCv = $('#leg'), lctx = legCv.getContext('2d');\n  let LW = 0, LH = 0, diagOn = false;\n  function sizeLeg() {\n    const r = legCv.getBoundingClientRect(); LW = r.width || 340; LH = r.height || 260;\n    legCv.width = Math.round(LW * dpr); legCv.height = Math.round(LH * dpr);\n  }\n  const dbuf = new Float64Array(16);\n  function drawDiagram() {\n    const x = lctx;\n    x.setTransform(dpr, 0, 0, dpr, 0, 0);\n    x.clearRect(0, 0, LW, LH);\n    // leg space bounds: x -118..22, y -97..40\n    const k = Math.min((LW - 60) / 150, (LH - 22) / 140);\n    const ox = LW / 2 - (-50) * k, oy = 16 + 40 * k;\n    const T = (px, py) => [ox + px * k, oy - py * k];\n    const o = solve(theta, dbuf);\n    // foot trajectory\n    x.strokeStyle = '#d4553a'; x.lineWidth = 1.4; x.setLineDash([4, 3]);\n    x.beginPath(); CURVE.forEach(([cx, cy], q) => { const [px, py] = T(cx, cy); if (q) x.lineTo(px, py); else x.moveTo(px, py); }); x.stroke();\n    x.setLineDash([]);\n    // crank circle\n    const [c0x, c0y] = T(0, 0);\n    x.strokeStyle = 'rgba(46,59,68,.35)'; x.lineWidth = 1; x.beginPath(); x.arc(c0x, c0y, L.m * k, 0, Math.PI * 2); x.stroke();\n    // dimension lines for a and l\n    const [zx, zy] = T(-L.a, -L.l);\n    x.strokeStyle = 'rgba(61,143,168,.8)'; x.fillStyle = 'rgba(61,143,168,.95)'; x.lineWidth = 0.8;\n    x.font = '10px ' + getComputedStyle(document.body).getPropertyValue('--mono');\n    // a: horizontal offset, dimensioned below the foot's reach of the crank circle, well clear of the links\n    const dimY = T(0, 37)[1];\n    x.setLineDash([2, 2]);\n    x.beginPath(); x.moveTo(zx, zy - 5); x.lineTo(zx, dimY - 4); x.moveTo(c0x, c0y - L.m * k - 2); x.lineTo(c0x, dimY - 4); x.stroke();\n    x.setLineDash([]);\n    x.beginPath(); x.moveTo(zx, dimY); x.lineTo(c0x, dimY); x.stroke();\n    x.beginPath(); x.moveTo(zx + 5, dimY - 3); x.lineTo(zx, dimY); x.lineTo(zx + 5, dimY + 3); x.moveTo(c0x - 5, dimY - 3); x.lineTo(c0x, dimY); x.lineTo(c0x - 5, dimY + 3); x.stroke();\n    x.fillText('a 38', (zx + c0x) / 2 - 12, dimY - 4);\n    // l: vertical offset, just outside the crank circle\n    const lx = c0x + L.m * k + 10;\n    x.beginPath(); x.moveTo(c0x + L.m * k + 2, c0y); x.lineTo(lx + 4, c0y); x.moveTo(zx + 6, zy); x.lineTo(lx + 4, zy); x.moveTo(lx, c0y); x.lineTo(lx, zy); x.stroke();\n    x.fillText('l 7.8', lx + 6, (c0y + zy) / 2 + 4);\n    // links, with their names and lengths\n    const pts = []; for (let q = 0; q < 16; q += 2) pts.push(T(o[q], o[q + 1]));\n    x.fillStyle = 'rgba(244,227,161,.35)';\n    x.beginPath(); x.moveTo(pts[1][0], pts[1][1]); x.lineTo(pts[3][0], pts[3][1]); x.lineTo(pts[5][0], pts[5][1]); x.closePath(); x.fill();\n    x.beginPath(); x.moveTo(pts[4][0], pts[4][1]); x.lineTo(pts[6][0], pts[6][1]); x.lineTo(pts[7][0], pts[7][1]); x.closePath(); x.fill();\n    x.strokeStyle = '#2e3b44'; x.lineWidth = 1.6; x.lineCap = 'round';\n    for (const [aI, bI] of LINKS) { x.beginPath(); x.moveTo(pts[aI][0], pts[aI][1]); x.lineTo(pts[bI][0], pts[bI][1]); x.stroke(); }\n    x.fillStyle = '#2e3b44';\n    for (const [aI, bI, nm] of LINKS) {\n      const mx = (pts[aI][0] + pts[bI][0]) / 2, my = (pts[aI][1] + pts[bI][1]) / 2;\n      const dx = pts[bI][0] - pts[aI][0], dy = pts[bI][1] - pts[aI][1], len = Math.hypot(dx, dy) || 1;\n      const nx = -dy / len, ny = dx / len, off = nm === 'm' ? 9 : 8;\n      const label = nm + ' ' + L[nm];\n      const tw = x.measureText(label).width;\n      const lx = mx + nx * off - tw / 2, ly = my + ny * off + 3;\n      x.fillStyle = 'rgba(251,250,244,.85)'; x.fillRect(lx - 2, ly - 9, tw + 4, 12);\n      x.fillStyle = nm === 'm' ? '#3d8fa8' : '#2e3b44'; x.fillText(label, lx, ly);\n    }\n    // joints and the hatched fixed pivots\n    for (let q = 1; q < 7; q++) { x.fillStyle = '#fbfaf4'; x.beginPath(); x.arc(pts[q][0], pts[q][1], 3.2, 0, Math.PI * 2); x.fill(); x.strokeStyle = '#2e3b44'; x.lineWidth = 1.2; x.stroke(); }\n    for (const q of [0, 1]) {\n      const [px, py] = pts[q];\n      x.strokeStyle = '#2e3b44'; x.lineWidth = 1.1;\n      x.beginPath(); x.moveTo(px - 8, py + 8); x.lineTo(px + 8, py + 8); x.moveTo(px, py); x.lineTo(px - 5, py + 8); x.moveTo(px, py); x.lineTo(px + 5, py + 8); x.stroke();\n      for (let hI = -8; hI < 8; hI += 4) { x.beginPath(); x.moveTo(px + hI, py + 8); x.lineTo(px + hI - 3, py + 12); x.stroke(); }\n      x.fillStyle = '#2e3b44'; x.beginPath(); x.arc(px, py, 2.6, 0, Math.PI * 2); x.fill();\n    }\n    const [fx, fy] = pts[7];\n    x.fillStyle = '#d4553a'; x.beginPath(); x.arc(fx, fy, 4.2, 0, Math.PI * 2); x.fill();\n    x.fillStyle = '#d4553a'; x.fillText('foot', fx + 7, fy + 12);\n    x.fillStyle = 'rgba(46,59,68,.7)'; x.fillText('crank', c0x + 6, c0y + L.m * k + 12);\n  }\n\n  /* ================= sound: wind and soft footfalls ================= */\n  let actx = null, windGain = null, windFilter = null, soundOn = false;\n  function ensureAudio() {\n    if (actx) return true;\n    try {\n      const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return false;\n      actx = new AC();\n      const buf = actx.createBuffer(1, actx.sampleRate * 2, actx.sampleRate), d = buf.getChannelData(0);\n      let last = 0; for (let q = 0; q < d.length; q++) { last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02; d[q] = last * 3.5; }\n      const src = actx.createBufferSource(); src.buffer = buf; src.loop = true;\n      windFilter = actx.createBiquadFilter(); windFilter.type = 'bandpass'; windFilter.frequency.value = 500; windFilter.Q.value = 0.6;\n      windGain = actx.createGain(); windGain.gain.value = 0;\n      src.connect(windFilter); windFilter.connect(windGain); windGain.connect(actx.destination); src.start();\n      return true;\n    } catch (e) { actx = null; return false; }\n  }\n  function windSound() {\n    if (!actx) return;\n    const t = actx.currentTime, gust = 0.5 + 0.5 * Math.sin(time * 0.7) * Math.sin(time * 0.23);\n    windGain.gain.setTargetAtTime(soundOn ? (0.02 + windShown * 0.012) * (0.7 + gust * 0.6) : 0, t, 0.3);\n    windFilter.frequency.setTargetAtTime(300 + windShown * 60 + gust * 200, t, 0.3);\n  }\n  let lastTock = 0;\n  function tock(depth) {\n    if (!actx) return;\n    const now = performance.now(); if (now - lastTock < 70) return; lastTock = now;\n    const t = actx.currentTime, o = actx.createOscillator(), g = actx.createGain();\n    o.type = 'triangle'; o.frequency.setValueAtTime(depth ? 180 : 230, t); o.frequency.exponentialRampToValueAtTime(90, t + 0.08);\n    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(depth ? 0.03 : 0.05, t + 0.005); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.12);\n    o.connect(g); g.connect(actx.destination); o.start(t); o.stop(t + 0.15);\n  }\n\n  /* ================= controls ================= */\n  const windEl = $('#wind'), windOut = $('#windOut');\n  function setWind(v) { wind = v; windOut.textContent = v.toFixed(1) + ' m/s'; }\n  windEl.addEventListener('input', () => setWind(+windEl.value));\n  $('#lessBtn').addEventListener('click', () => { if (pairs > 1) { pairs--; buildLegs(); if (window.innerWidth < 720) resize(); } });\n  $('#moreBtn').addEventListener('click', () => { if (pairs < 8) { pairs++; buildLegs(); if (window.innerWidth < 720) resize(); } });\n  const diagBtn = $('#diagBtn'), diagram = $('#diagram');\n  function setDiag(v) { diagOn = v; diagram.hidden = !v; diagBtn.setAttribute('aria-pressed', String(v)); if (v) { sizeLeg(); drawDiagram(); } }\n  diagBtn.addEventListener('click', () => setDiag(!diagOn));\n  const traceBtn = $('#traceBtn');\n  traceBtn.addEventListener('click', () => { trace = !trace; traceBtn.setAttribute('aria-pressed', String(trace)); });\n  const followBtn = $('#followBtn');\n  function setFollow(v) { follow = v; followBtn.setAttribute('aria-pressed', String(v)); }\n  followBtn.addEventListener('click', () => setFollow(!follow));\n  const soundBtn = $('#soundBtn');\n  soundBtn.addEventListener('click', () => {\n    if (!soundOn) { if (!ensureAudio()) return; if (actx.state === 'suspended') actx.resume(); }\n    soundOn = !soundOn; soundBtn.setAttribute('aria-pressed', String(soundOn));\n    if (!soundOn && windGain) windGain.gain.setTargetAtTime(0, actx.currentTime, 0.1);\n  });\n\n  // drag to pan along the beach\n  let drag = null;\n  stage.addEventListener('pointerdown', (e) => {\n    if (e.button !== 0 || e.target.closest('.label,.hud')) return;\n    drag = { x: e.clientX, y: e.clientY, cam: camX, moved: false, id: e.pointerId };\n  });\n  window.addEventListener('pointermove', (e) => {\n    if (!drag || e.pointerId !== drag.id) return;\n    const dx = e.clientX - drag.x, dy = e.clientY - drag.y;\n    if (!drag.moved) {\n      if (Math.abs(dx) < 6) return;\n      if (e.pointerType === 'touch' && Math.abs(dy) > Math.abs(dx)) { drag = null; return; }   // let the page scroll\n      drag.moved = true; setFollow(false); $('#scene').classList.add('dragging');\n      try { stage.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }\n      $('#hint').style.opacity = '0';\n    }\n    camX = drag.cam - dx / S;\n  });\n  const endDrag = () => { drag = null; $('#scene').classList.remove('dragging'); };\n  window.addEventListener('pointerup', endDrag); window.addEventListener('pointercancel', endDrag);\n  stage.addEventListener('touchmove', (e) => { if (drag && drag.moved) e.preventDefault(); }, { passive: false });\n  cv.addEventListener('keydown', (e) => {\n    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') { e.preventDefault(); setFollow(false); camX += (e.key === 'ArrowLeft' ? -1 : 1) * 60 * (e.shiftKey ? 4 : 1); }\n    else if (e.key === 'Home') { e.preventDefault(); setFollow(true); }\n  });\n  document.addEventListener('keydown', (e) => {\n    if (e.ctrlKey || e.metaKey || e.altKey) return;\n    const tag = e.target && e.target.tagName; if (tag === 'INPUT') return;\n    if (e.key === '+' || e.key === '=') $('#moreBtn').click();\n    else if (e.key === '-' || e.key === '_') $('#lessBtn').click();\n    else if (e.key === 'd' || e.key === 'D') setDiag(!diagOn);\n    else if (e.key === 't' || e.key === 'T') traceBtn.click();\n    else if (e.key === 'f' || e.key === 'F') setFollow(!follow);\n  });\n\n  let rt = 0;\n  window.addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(resize, 60); });\n  if (mq.addEventListener) mq.addEventListener('change', (e) => { reduce = e.matches; });\n\n  /* ================= boot: a few seconds of walking so the sand already holds footprints ================= */\n  buildLegs();\n  resize();\n  if (reduce) { setWind(2.5); windEl.value = 2.5; windShown = 2.5; }\n  for (let q = 0; q < 540; q++) { step(1 / 60); for (const p of prints) if (p.on) p.age += 1 / 60; }\n  camX = bodyX + 8;\n  hud();\n  requestAnimationFrame(frame);\n})();\n</script>\n</body>\n</html>\n";
